/* Progressive enhancement: content stays visible without animation support. */
(()=>{'use strict';const reduced=matchMedia('(prefers-reduced-motion: reduce)');let observer;
 const reveal=()=>{if(reduced.matches||!('IntersectionObserver' in window))return;document.documentElement.classList.add('motion-ready');observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}},{threshold:.06});document.querySelectorAll('.hero-copy,.book-scene,.collection-ribbon,.section-head,.volume,.paper-card,.chapter-header,.reader-desk,.progress-item').forEach((el,i)=>{if(el.classList.contains('is-visible'))return;el.classList.add('reveal-item');el.style.setProperty('--reveal-delay',`${Math.min(i%6,3)*65}ms`);observer.observe(el)})};
 document.addEventListener('nihongo:render',reveal);document.addEventListener('DOMContentLoaded',reveal);reveal();
 document.addEventListener('pointermove',event=>{if(reduced.matches||event.pointerType!=='mouse')return;const scene=event.target.closest?.('.book-scene');if(!scene)return;const r=scene.getBoundingClientRect();scene.style.setProperty('--scene-x',`${((event.clientX-r.left)/r.width-.5)*10}deg`);scene.style.setProperty('--scene-y',`${-((event.clientY-r.top)/r.height-.5)*7}deg`)},{passive:true});document.addEventListener('pointerout',event=>{const scene=event.target.closest?.('.book-scene');if(scene&&!scene.contains(event.relatedTarget)){scene.style.removeProperty('--scene-x');scene.style.removeProperty('--scene-y')}},{passive:true});
 reduced.addEventListener?.('change',()=>{if(reduced.matches){observer?.disconnect();document.documentElement.classList.remove('motion-ready')}else reveal()});
})();
